<template>
  <div class="editable-skill">
    <input 
      v-model="skillName" 
      class="skill-box" 
      type="text" 
      @input="adjustWidth" 
      ref="inputBox" 
    />
    <span ref="hiddenSpan" class="hidden-span">{{ skillName || "..." }}</span>
  </div>
</template>

<script lang="ts">
import Vue from "vue";

export default Vue.extend({
  name: "EditableSkill",
  props: {
    name: {
      type: String,
      required: true,
    },
  },
  data() {
    return {
      skillName: this.name,
    };
  },
  mounted() {
    this.adjustWidth();
  },
  methods: {
    adjustWidth() {
      const input = this.$refs.inputBox as HTMLInputElement;
      const span = this.$refs.hiddenSpan as HTMLSpanElement;

      if (input && span) {
        // Get text width dynamically
        const newWidth = span.offsetWidth + 20; 
        input.style.width = `${Math.max(newWidth, 50)}px`; // Minimum width of 50px
      }
    },
  },
});
</script>

<style scoped>
.editable-skill {
  display: inline-flex;
  align-items: center;
  margin: 5px;
}

.skill-box {
  background-color: #434348;
  color: white;
  border: 1px solid white;  /* White border */
  padding: 10px 12px;
  border-radius: 5px;
  font-size: 16px;
  font-weight: 100;
  outline: none;
  font-style: sans-serif;
  width: fit-content;
  transition: width 0.2s ease-in-out;
}

.skill-box:focus {
  border-color: #fff;
}

/* Hidden span for dynamic width calculation */
.hidden-span {
  position: absolute;
  visibility: hidden;
  white-space: nowrap;
  font-size: 16px;
  padding: 10px 12px;
}
</style>
